type Item = { type: string; cursed?: boolean; enchantment?: number };

const basePremiumsByType: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25, moonstone: 25 };

const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const sumOverItems = (items: Item[], perItem: (item: Item) => number): number =>
  items.reduce((sum, item) => sum + perItem(item), 0);

const basePremiumForItem = (item: Item): number => basePremiumsByType[item.type];

const sumOfItemBasePremiums = (items: Item[]): number =>
  sumOverItems(items, basePremiumForItem);

const groupByType = (items: Item[]): Item[][] => {
  const groups = new Map<string, Item[]>();
  for (const item of items) {
    const group = groups.get(item.type) ?? [];
    group.push(item);
    groups.set(item.type, group);
  }
  return [...groups.values()];
};

const basePremiumForGroup = (group: Item[]): number =>
  group.length === BLOCK_SIZE ? BLOCK_PREMIUM : sumOfItemBasePremiums(group);

export const basePremium = (items: Item[]): number =>
  groupByType(items).reduce((sum, group) => sum + basePremiumForGroup(group), 0);

const PROCESSING_FEE = 5;

type Customer = { yearsWithMHPCO: number };
type QuoteStep = { op: "quote"; items: Item[] };
type Scenario = { customer: Customer; steps: QuoteStep[] };

const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_RATE = 0.3;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const FIRST_INSURANCE_RATE = 0.1;
const LOYALTY_RATE = 0.2;
const LOYALTY_THRESHOLD = 2;

const surchargeOf = (item: Item, rate: number): number => basePremiumForItem(item) * rate;

const curseSurchargeForItem = (item: Item): number =>
  item.cursed ? surchargeOf(item, CURSE_SURCHARGE_RATE) : 0;

const curseSurcharge = (items: Item[]): number =>
  sumOverItems(items, curseSurchargeForItem);

const highEnchantmentSurchargeForItem = (item: Item): number =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
    ? surchargeOf(item, HIGH_ENCHANTMENT_RATE)
    : 0;

const highEnchantmentSurcharge = (items: Item[]): number =>
  sumOverItems(items, highEnchantmentSurchargeForItem);

const firstInsuranceSurcharge = (policyBase: number): number => policyBase * FIRST_INSURANCE_RATE;

const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD ? policyBase * LOYALTY_RATE : 0;

const itemSurcharges = (items: Item[]): number =>
  curseSurcharge(items) + highEnchantmentSurcharge(items);

const quotePremium = (step: QuoteStep, customer: Customer): number => {
  const items = step.items;
  const policyBase = basePremium(items);
  const surcharges = itemSurcharges(items) + firstInsuranceSurcharge(policyBase);
  return policyBase + surcharges - loyaltyDiscount(policyBase, customer) + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): { results: { premium: number }[] } => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step, scenario.customer) })),
});

