const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;

const insuranceValuesByType: Record<string, number> = { sword: 1000, amulet: 600, staff: 800, potion: 400, rune: 250, moonstone: 250 };

const insuranceValue = (item: Item): number => insuranceValuesByType[item.type];

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + insuranceValue(item), 0);

const payoutForDamage = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const claimResult = (step: ClaimStep, scenario: Scenario): ClaimResult => {
  const policy = scenario.steps[step.policy] as QuoteStep;
  const cap = insuranceSum(policy.items) * CAP_MULTIPLIER;
  const payout = step.incident.damages.reduce((sum, damage) => sum + payoutForDamage(damage), 0);
  return { payout, remainingCap: cap - payout };
};

export const runScenario = (scenario: Scenario): { results: StepResult[] } => ({
  results: scenario.steps.map((step, index) =>
    step.op === "quote"
      ? { premium: quotePremium(step, scenario.customer, index > 0) }
      : claimResult(step, scenario),
  ),
});

